from pathlib import Path
import hashlib,itertools

def entries(root,dirs=False):
 r=Path(root); out=[]
 for p in sorted(r.rglob('*')):
  rel=p.relative_to(r).as_posix().encode()
  if p.is_file(): out.append((b'f',rel,p.read_bytes()))
  elif dirs and p.is_dir(): out.append((b'd',rel,b''))
 return out

def candidates(root,target):
 for dirs in [False,True]:
  es=entries(root,dirs)
  for content_kind in ['bytes','hex','raw']:
   for type_mode in ['none','char','word']:
